	 * 
	 * @param direction can be {@literal null}.
	 * @param paths must not be {@literal null}.
	 * @return
	 */
	public JpaSort and(Direction direction, Path<?, ?>... paths) {

		Assert.notNull(paths, "Paths must not be null!");

