    DEBUG > 2 && console.error("-- Data received from RN Client: state = " + state)
    DEBUG > 2 && console.error("-- chunk length: " + chunk.length)
    DEBUG > 2 && console.error("-- buffer length(original): " + buffer.length)

    if (chunk == null || state === 'eof')
