     acquireExclusiveLock();
     try {
       final String id = "OS" + System.currentTimeMillis() + random.nextLong();
       sessions.put(id, new OHttpSession(id, iDatabaseName, iUserName, iUserPassword));
       return id;

     } finally {
       releaseExclusiveLock();
     }
   }

